UPDATE email_templates SET text_body = 'Hi {{name}},\n\nThank you for taking a moment to share your availability. We know coordinating calendars can sometimes feel awkward, so you can relax knowing your preferred time has been recorded safely.\n\nThe organizer will review your request and contact you as soon as the meeting is confirmed. You do not need to do anything else right now.' WHERE template_key = 'received' AND updated_by IS NULL;
UPDATE email_templates SET text_body = 'Hi {{name}},\n\nGreat news, your meeting is confirmed and your time has been reserved. Everything you need to join is included below.\n\nA calendar invitation is attached too, so you can add the meeting to your calendar and receive reminders from your preferred calendar app. We are looking forward to the conversation.' WHERE template_key = 'meeting_details' AND updated_by IS NULL;
UPDATE email_templates SET text_body = 'Hi {{name}},\n\nJust a thoughtful reminder that your meeting is coming up soon. We are looking forward to speaking with you and hope the scheduled time still works comfortably.\n\nUse the button below when it is time to join. The calendar invitation is attached again for convenience. If anything has changed, contact the organizer and let them know.' WHERE template_key = 'reminder' AND updated_by IS NULL;
UPDATE email_templates SET text_body = 'Hi {{name}},\n\nWe missed you at the meeting and hope everything is okay. Please do not worry or feel awkward about it. Busy days happen, technology can fail, and plans sometimes change without warning.\n\nWhenever you are ready, contact the organizer. We will be happy to find another time that feels easier and works better for you.' WHERE template_key = 'missed' AND updated_by IS NULL;
UPDATE email_templates SET text_body = 'Hi {{name}},\n\nSometimes calendars shift, and that is completely understandable. We need to move this meeting, but choosing another time should be simple.\n\nUse the button below to review the available slots and select the one that works best for you. We appreciate your flexibility and look forward to connecting soon.' WHERE template_key = 'reschedule' AND updated_by IS NULL;
UPDATE email_templates SET text_body = 'Hi {{name}},\n\nWe are sorry, but the planned meeting has been cancelled. We understand that changes like this can be inconvenient, and we appreciate the time you had already set aside.\n\nIf you would still like to connect, please contact the organizer whenever you are ready. They will be glad to help arrange another conversation.' WHERE template_key = 'cancelled' AND updated_by IS NULL;
